import{_ as a,o as s,c as e,am as p}from"./chunks/framework.CiF4W93w.js";const h=JSON.parse('{"title":"SpringCloud_Nacos-基础使用","description":"","frontmatter":{"title":"SpringCloud_Nacos-基础使用","excerpt":"摘要","date":"2025-07-12 22:35:49","updated":"2025-07-12 22:35:49"},"headers":[],"relativePath":"框架/微服务&分布式/框架 SpringCloud/SpringCloud_Nacos-基础使用.md","filePath":"框架/微服务&分布式/框架 SpringCloud/SpringCloud_Nacos-基础使用.md","lastUpdated":null}'),l={name:"框架/微服务&分布式/框架 SpringCloud/SpringCloud_Nacos-基础使用.md"};function i(t,n,o,c,r,d){return s(),e("div",null,[...n[0]||(n[0]=[p(`<h3 id="基础概念" tabindex="-1">基础概念 <a class="header-anchor" href="#基础概念" aria-label="Permalink to &quot;基础概念&quot;">​</a></h3><blockquote><p>Namespace+Group+DataID三者的关系</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202311250024118.png" alt="image.png|400"></p><blockquote><p>多环境配置</p></blockquote><p>略</p><h4 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h4><p>命名空间id用于唯一标识命名空间， 新建命名空间时候，如果不填写命名空间id，则系统会自动生成命名空间id，生成规则为UUID方式。</p><p>但在spring 项目中集成nacos 的时候，配置文件中填写的namespace就是命名空间的id</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202311260000905.png" alt="image.png"></p><p>因此尽量保持nacos的命名空间名称和id 一致</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202311260002165.png" alt="image.png"></p><h3 id="服务发现" tabindex="-1">服务发现 <a class="header-anchor" href="#服务发现" aria-label="Permalink to &quot;服务发现&quot;">​</a></h3><p>在 spring-cloud-alibaba-service 的主启动类上，使用 @EnableDiscoveryClient 注解开启 Nacos 服务发现功能</p><p>你访问该服务下的某个请求链接，再查看 nacos “服务管理”下的“服务列表”，会发现已经注册上了。</p><p>一般在消费端会引入 spring-cloud-loadbalancer 进行调用服务提供者提供的服务</p><hr><p>参考： <a href="https://cloud.tencent.com/developer/article/2226330" target="_blank" rel="noreferrer">https://cloud.tencent.com/developer/article/2226330</a></p><p>服务发现是先获取本地缓存，如果没有本地缓存，就请求<code>Nacos Server</code>服务端获取数据，如果<code>Nacos Server</code>挂了，也不会影响服务的调用。</p><p>服务发现：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240423182313.png" alt="image.png"></p><h3 id="配置中心" tabindex="-1">配置中心 <a class="header-anchor" href="#配置中心" aria-label="Permalink to &quot;配置中心&quot;">​</a></h3><blockquote><p><strong>动态获取配置内容</strong></p></blockquote><p>在应用的 POM 文件中引入 spring-cloud-starter-alibaba-nacos-config ，可实现配置的获取与动态刷新</p><p>示例</p><p>bootstrap.yml 文件配置</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server:</span></span>
<span class="line"><span>  port: 3377 #端口号</span></span>
<span class="line"><span>spring:</span></span>
<span class="line"><span>  application:</span></span>
<span class="line"><span>    name: config-client #服务名</span></span>
<span class="line"><span>  cloud:</span></span>
<span class="line"><span>    nacos:</span></span>
<span class="line"><span>      discovery:</span></span>
<span class="line"><span>        server-addr: 127.0.0.1:8848 #Nacos服务注册中心地址</span></span>
<span class="line"><span>      config:</span></span>
<span class="line"><span>        server-addr: 127.0.0.1:8848 #Nacos作为配置中心地址</span></span>
<span class="line"><span>        file-extension: yaml #指定yaml格式的配置</span></span>
<span class="line"><span>  profiles:</span></span>
<span class="line"><span>    active: dev #激活 dev 的配置</span></span></code></pre></div><p>在 icu.luoqi.nacos.controller 包下，创建一个名为 ConfigClientController 的 Controller 类，并在该类上使用 @RefreshScope 注解实现配置的自动更新，代码如下</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import org.springframework.beans.factory.annotation.Value;</span></span>
<span class="line"><span>import org.springframework.cloud.context.config.annotation.RefreshScope;</span></span>
<span class="line"><span>import org.springframework.web.bind.annotation.GetMapping;</span></span>
<span class="line"><span>import org.springframework.web.bind.annotation.RestController;</span></span>
<span class="line"><span>@RestController</span></span>
<span class="line"><span>@RefreshScope</span></span>
<span class="line"><span>public class ConfigClientController {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Value(&quot;\${config.info}&quot;)</span></span>
<span class="line"><span>    private String ConfigInfo;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    @GetMapping(&quot;/config/info&quot;)</span></span>
<span class="line"><span>    public String getConfigInfo(){</span></span>
<span class="line"><span>        return ConfigInfo;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>主启动类上，使用 @EnableDiscoveryClient 注解开启服务发现功能</p><p>启动 Nacos Server，并在 Nacos Server 控制台的“配置管理”下的“配置列表”中，点击“+”按钮，新建如下配置</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Data ID:        config-client-dev.yaml</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Group:          DEFAULT_GROUP</span></span>
<span class="line"><span></span></span>
<span class="line"><span>配置格式:       YAML</span></span>
<span class="line"><span></span></span>
<span class="line"><span>配置内容:       config:</span></span>
<span class="line"><span>                   info: xxxx</span></span></code></pre></div><p>在 Nacos Server 中，配置的 dataId（即 Data ID）的完整格式如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>\${prefix}-\${spring.profiles.active}.\${file-extension}</span></span></code></pre></div><p>启动该服务，并使用浏览器访问“<a href="http://localhost:3377/config/info%E2%80%9D%EF%BC%8C" target="_blank" rel="noreferrer">http://localhost:3377/config/info”，</a></p><p>在这种情况下，能够实现不重启后台服务，当你手动修改 nacos 的配置时，能够动态获取到配置内容。</p><blockquote><p>Nacos Config配置集的三种方式和加载顺序</p></blockquote><ul><li>通过 spring.cloud.nacos.config.shared-configs 配置项，支持多个共享 Nacos 配置集。</li><li>通过 spring.cloud.nacos.config.extension-configs 配置项，支持多个拓展 Nacos 配置集。</li><li>通过 spring.cloud.nacos.config.name 配置项，支持一个 Nacos 配置集。</li></ul><p>当三种方式共同使用时，它们的优先级关系是：A &lt; B &lt; C。另外，A 和 B 的命名带有“共享”或是“拓展”，没有任何含义，只是优先级不同</p><hr><p>参考</p><ul><li><a href="https://blog.csdn.net/qq_36903261/article/details/106835279" target="_blank" rel="noreferrer">https://blog.csdn.net/qq_36903261/article/details/106835279</a></li><li><a href="https://m.biancheng.net/springcloud/nacos.html" target="_blank" rel="noreferrer">https://m.biancheng.net/springcloud/nacos.html</a></li><li><a href="https://nacos.io/zh-cn/docs/v2/ecology/use-nacos-with-spring-cloud.html" target="_blank" rel="noreferrer">https://nacos.io/zh-cn/docs/v2/ecology/use-nacos-with-spring-cloud.html</a></li><li><a href="https://nacos.io/zh-cn/docs/quick-start-spring-cloud.html" target="_blank" rel="noreferrer">https://nacos.io/zh-cn/docs/quick-start-spring-cloud.html</a></li><li><a href="https://blog.csdn.net/weixin_45397785/article/details/128076533" target="_blank" rel="noreferrer">https://blog.csdn.net/weixin_45397785/article/details/128076533</a></li><li><a href="https://blog.csdn.net/ysj1241267542/article/details/112562611" target="_blank" rel="noreferrer">https://blog.csdn.net/ysj1241267542/article/details/112562611</a></li><li><a href="https://blog.csdn.net/u010520146/article/details/118703413" target="_blank" rel="noreferrer">https://blog.csdn.net/u010520146/article/details/118703413</a></li><li><a href="https://blog.csdn.net/wangwei021933/article/details/129590430" target="_blank" rel="noreferrer">https://blog.csdn.net/wangwei021933/article/details/129590430</a></li></ul>`,41)])])}const u=a(l,[["render",i]]);export{h as __pageData,u as default};
